export const ARCHIVE_EXTRACTS: Record<string, ArchiveExtract> = {
  "drishtidan-1948": { wikiTitle: "Drishtidan", extract: "Drishtidan (Donating Eyes) (1948) is an Indian Bengali feature film directed by Nitin Bose. Based on Rabindranth Tagore's story of the same name, the film narrates the evolving relationship of a blind woman with her husband. Legendary actor Uttam Kumar debuted in this film, who later became one of the greatest actors in the history of Indian Cinema and the most popular and successful film stars in the history of Bengali Cinema.", director: "Nitin Bose" },
  "kamona-1949": { wikiTitle: "Kamona", extract: "Kamona (transl. Desire) is a Bengali drama film directed by Nabendu Sundar. This movie was released on 4 March 1949 under the banner of Kirti Pictures. This is the second film of iconic legendary Bengali actor Uttam Kumar after Drishtidan and debut as the leading person crediting him as Uttam Chatterjee instead of Arun Kumar Chatterjee.", director: "Nabendu Sundar" },
  "maryada-1950": { wikiTitle: "Maryada (1950 film)", extract: "Maryada (transl. dignity) was a Bengali drama film directed by Digambar Chattopadhyay. This movie was released on 15 December 1950 under the banner of Bhabani Kalamandir Limited. This is the third and first movie of legendary Bengali actor Uttam Kumar and that Bibhu Bhattacharya appeared respectively.", director: "Digambar Chattopadhyay" },
  "ore-jatri-1951": { wikiTitle: "Ore Jatri", extract: "Ore Jatri is a Bengali drama film directed by Rajen Choudhury and director of photography Anil Gupta. It was released on 1 January 1951 under the banner of Kalpa Chitramandir production company. The film has Uttam Kumar and Prabha Devi in the lead roles.", director: "Rajen Choudhury" },
  "sahajatri-1951": { wikiTitle: "Sahajatri", extract: "Sahajatri was a Bengali drama film directed by Agradoot. This movie was released on 10 March 1951 under the banner of M. P. Productions Pvt. Ltd.", director: "Agradoot" },
  "nastaneer-1951": { wikiTitle: "Nastaneer", extract: "Nastaneer (transl. The Broken Nest) is a Bengali drama film directed by Pashupati Chatterjee. This movie was released in 1951 under the banner of M. P. Productions Pvt. Ltd.", director: "Pashupati Chatterjee" },
  "sanjibani-1952": { wikiTitle: "Sanjibani", extract: "Sanjibani is a Bengali drama film directed by Sukumar Dasgupta. This movie was released under the banner of M. P. Productions Pvt. Ltd.", director: "Sukumar Dasgupta" },
  "basu-paribar-1952": { wikiTitle: "Basu Paribaar (1952 film)", extract: "Basu Poribar (transl. Bose Family) is a 1952 Bengali film directed by Nirmal Dey under the banner of M.P Productions. Uttam Kumar, Sabitri Chatterjee, Supriya Devi, Bhanu Banerjee and Jiben Bose play lead roles. The film was released on 11 April 1952.", director: "Nirmal Dey" },
  "kar-pape-1952": { wikiTitle: "Kar Pape", extract: "Kar Pape (The Sinner) is a Bengali social drama film written and directed by Kali Prasad Ghosh and produced by M.P. Productions. The film was released on 15 August 1952, under the banner of Shankar Pictures. It is the first time in history that an adult Bengali film raising awareness about sexually transmitted diseases was made.", director: "Kali Prasad Ghosh" },
  "sharey-chuattor-1953": { wikiTitle: "Sharey Chuattor", extract: "Sharey Chuattor (lit. 'Seventy-four and a Half') is a 1953 Indian Bengali comedy film, directed by Nirmal Dey, based on a story novel by Bijon Bhattacharya. The film stars Tulsi Chakraborty and Molina Devi in the lead and co-stars Uttam Kumar, Suchitra Sen, Bhanu Bandopadhyay, Jahor Roy and Nabadwip Haldar. Contemporary playback singers like Dhananjay, Dwijen Mukherjee, Shyamal Mitra, and Manabendra Mukherjee also acted in this film.", director: "Nirmal Dey" },
  "lakh-taka-1953": { wikiTitle: "Lakh Taka", extract: "Lakh Taka is a Bengali drama film directed by Niren Lahiri, and starring Uttam Kumar, Sabitri Chatterjee, Bhanu Banerjee, Chhabi Biswas and Jahor Roy. The music direction is by Shyamal Mitra and Niren Lahiri. It was released on 1 January 1953 under the banner of Satabdi Chitra Pratisthan.", director: "Niren Lahiri" },
  "nabin-jatra-1953": { wikiTitle: "Nabin Jatra", extract: "Nabin Jatra was a Bengali drama film directed by Subodh Mitra. This film was released on 11 September 1953 under the banner of New Theatres. Pankaj Mullick was the music director of the movie.", director: "Subodh Mitra" },
  "bou-thakuranir-haat-1953": { wikiTitle: "Bou Thakuranir Haat", extract: "Bou Thakuranir Haat is a 1953 Bengali drama film directed by Naresh Mitra based on a novel of Rabindranath Tagore of the same name, published in 1883. This film was released under the banner of Emar Productions. It stars Uttam Kumar, Pahadi Sanyal in the lead with Sambhu Mitra, Bhanu Bandyopadhyay and others.", director: "Naresh Mitra" },
  "moner-mayur-1954": { wikiTitle: "Moner Mayur", extract: "Moner Mayur was a Bengali drama film directed by Sushil Majumdar based on a story of Bengali novelist Protiva Bose. This movie was released in 1954 under the banner of Rama Chhayachitra Ltd. The music direction was done by Satyajit Majumdar.", director: "Sushil Majumdar" },
  "ora-thake-odhare-1954": { wikiTitle: "Ora Thake Odhare", extract: "Ora Thake Odhare (transl. They Live That Side) is a Bengali romantic comedy film directed by Sukumar Dasgupta based on a story by Premendra Mitra. This film was released on 5 February 1954 under the banner of S. M. Productions.", director: "Sukumar Dasgupta" },
  "champadangar-bou-1954": { wikiTitle: "Champadangar Bou", extract: "Champadangar Bou was a Bengali drama film directed by Nirmal Dey. This film was based on the story of Tarashankar Bandyopadhyay. This movie was released on 1954 in the banner of Nirmal Dey Productions.", director: "Nirmal Dey" },
  "maraner-pare-1954": { wikiTitle: "Maraner Pare", extract: "Maraner Pare was a Bengali crime drama film directed by Satish Dasgupta. This movie was released on 1 Jan 1954 under the banner of Himalayan Art Producers. The music direction was done by Sargam Unit.", director: "Satish Dasgupta" },
  "sadanander-mela-1954": { wikiTitle: "Sadanander Mela", extract: "Sadanander Mela (; English: The House of Sadananda) is a Bengali drama film from 1954, directed by Sukumar Dasgupta. The story is written by Mani Burma and screenplay by Premendra Mitra. The film stars Bhanu Banerjee, Chhabi Biswas, Uttam Kumar, and Suchitra Sen.", director: "Sukumar Dasgupta" },
  "annapurnar-mandir-1954": { wikiTitle: "Annapurnar Mandir", extract: "Annapurnar Mandir (transl. Temple of Annapurna) is a Bengali social drama film directed by Naresh Mitra based on the novel of the same name by Nirupama Devi. This film was released on 6 August 1954 under the banner of Chitra Mandir and received 2nd National Film Awards in 1954. Uttam Kumar and Sabitri Chaterjee starred in the lead roles, with Suchitra Sen in a supporting role.", director: "Naresh Mitra" },
  "agni-pariksha-1954": { wikiTitle: "Agni Pariksha (1954 film)", extract: "Agni Pariksha (alternatively Agni Pareeksha or Agni Pariksha or Agnipariksha, transl. The Test Of Fire) is a 1954 Indian Bengali romantic drama film directed by Agradoot and starring Uttam Kumar and Suchitra Sen. The film was adapted from Asha Purna Devi's novel of the same name. The film became an overwhelming success critically and commercially.", director: "Agradoot" },
  "bakul-1954": { wikiTitle: "Bakul", extract: "Bakul was a Bengali drama film directed by Bholanath Mitra. This movie was released in 1954 under the banner of New Theatres. The music direction was done by Pranab Dey.", director: "Bholanath Mitra" },
  "grihapravesh-1954": { wikiTitle: "Grihapravesh (1954 film)", extract: "Grihapravesh is a Bengali drama film directed by Ajoy Kar. This movie was released on 12 Nov. 1954 under the banner of Naba Chitrabharati Ltd.", director: "Ajoy Kar" },
  "mantra-shakti-1954": { wikiTitle: "Mantra Shakti", extract: "Mantra Shakti (The Power of Chantis) is an Indian Bengali drama film directed by Chitta Basu and produced by Harendranath Chattopadhyay. It was released in 1954 under the banner of H. N. C. Productions.", director: "Chitta Basu" },
  "saajher-pradip-1955": { wikiTitle: "Saajher Pradip", extract: "Saajher Pradip is a 1955 Bengali film directed by Sudhangshu Mukherjee. It was written by Prabhabati Devi Saraswati and music was composed by Manabendra Mukherjee. This is a drama film.", director: "Sudhangshu Mukherjee" },
  "raikamal-1955": { wikiTitle: "Raikamal", extract: "Raikamal is a Bengali drama film directed by Subodh Mitra. The film stars Kaberi Bose, Uttam Kumar, Sabitri Chatterjee, Chandrabati Devi and others. Pankaj Kumar Mallick composed music in the film.", director: "Subodh Mitra" },
  "shap-mochan-1955": { wikiTitle: "Shap Mochan", extract: "Shap Mochan is a Bengali musical romance film directed and produced by Sudhir Mukherjee based on a novel Sandhyaraag of Falguni Mukhopadhyay. This film was released in 1955 under the banner of Production Syndicate starring Uttam Kumar and Suchitra Sen in lead. Music director of the film was Hemanta Kumar Mukhopadhyay." },
  "hrad-1955": { wikiTitle: "Hrad (film)", extract: "Hrad (The Lake) is a Bengali drama film directed by Ardhendu Sen. The film stars Uttam Kumar, Sandhyarani, Chhabi Biswas, Asit Baran. This film was released on 29 July 1955 under the banner of Rupmaya films.", director: "Ardhendu Sen" },
  "kankabatir-ghat-1955": { wikiTitle: "Kankabatir Ghat", extract: "Kankabatir Ghat is a 1955 Bengali film directed by Chitta Bose and produced by Harendranath Chattopadhyay. This film was written by Nripendrakrishna Chatterjee. This film was produced by Angel Digital Private Limited and distributed by Chitra Paribeshak.", director: "Chitta Bose" },
  "upahar-1955": { wikiTitle: "Upahar", extract: "Upahar is a Bengali drama film directed by Tapan Sinha based on a novel Krishna of Sailajananda Mukherjee. This film was produced by the Bani Chitram and release in 1955. It's starring Uttam Kumar, Manju Dey and Sabitri Chatterjee in lead.", director: "Tapan Sinha" },
  "bratacharini-1955": { wikiTitle: "Bratacharini", extract: "Bratacharini is a 1955 Bengali film directed by Kamal Ganguly. It stars Uttam Kumar and Sabitri Chatterjee in lead roles.", director: "Kamal Ganguly" },
  "raat-bhore-1955": { wikiTitle: "Raat Bhore", extract: "Raat Bhore is a 1955 Bengali drama film directed by Mrinal Sen, who also wrote the screenplay. This was Sen's first film.", director: "Mrinal Sen" },
  "sabar-uparey-1955": { wikiTitle: "Sabar Uparey", extract: "Sabar Uparey (Bengali pronunciation: [ʃaˈbaɾ uˈpaɾe] transl. Beyond All) is a 1955 Indian Bengali crime thriller film produced by M.P Production Private Ltd and directed by Agradoot, based on A.J. Cronin's 1953 novel, Beyond This Place. It stars Uttam Kumar and Suchitra Sen in leading roles. Chhabi Biswas, Pahari Sanyal and Nitish Mukherjee also play important roles in the movie.", director: "Agradoot" },
  "sagarika-1956": { wikiTitle: "Sagarika 1956", extract: "Sagarika is a 1956 Bengali romantic drama film directed by Agragami. The film has music composed by Robin Chatterjee. The film stars Uttam Kumar and Suchitra Sen as leads, with actors Jamuna Sinha, Namita Sinha, Kamal Mitra, Pahadi Sanyal, Jahar Ganguli, Anup Kumar in supporting roles.", director: "Agragami" },
  "saheb-bibi-golam-1956": { wikiTitle: "Saheb Bibi Golam (film)", extract: "Saheb Bibi Golam is a 1956 Bengali film directed by Kartik Chatterjee. It is based on a Bengali novelist Bimal Mitra's 1953 novel of the same name. The film explores the tragic fall of feudalism in Bengal during the British Raj.", director: "Kartik Chatterjee" },
  "chirakumar-sabha-1956": { wikiTitle: "Chirokumar Sabha", extract: "Chirakumar Sabha is a 1956 Indian Bengali comedy drama film directed by Debaki Bose and produced by Dilip based on Rabindranath Tagore's story. The film stars Uttam Kumar and Anita Guha in the lead roles with Ahindra Chowdhury and others. This film was released on 26 April 1956 in the banner of Dilip Pictures.", director: "Debaki Bose" },
  "ekti-raat-1956": { wikiTitle: "Ekti Raat", extract: "Ekti Raat (transl. One Night) is a 1956 Indian Bengali comedy film directed by Chitta Basu and produced by Harendranath Chattopadhyay based on, Bhimpalashree, a story of Bengali novelist Balai Chand Mukhopadhyay. The film stars Uttam Kumar and Suchitra Sen in the lead roles with Tulsi Chakraborty and Bhanu Banerjee.", director: "Chitta Basu" },
  "shankar-narayan-bank-1956": { wikiTitle: "Shankar Narayan Bank", extract: "Shankar Narayan Bank is a 1956 Bengali film directed by Niren Lahiri. This is a drama film which stars Chhabi Biswas Kaberi Bose, Chhaya Devi, Vasant Choudhury, Anubha Gupta, Anup Kumar and Uttam Kumar in the lead roles. This film was produced by Sunrise Films and distributed under the banner of Nandan Pictures.", director: "Niren Lahiri" },
  "shyamali-1956": { wikiTitle: "Shyamali", extract: "Shyamali is a 1956 Indian Bengali romantic drama film directed by Ajoy Kar and stars Kaberi Bose as the title character Shyamali. Uttam Kumar stars in this movie as the male protagonist. The film is based on the novel by same name of Nirupama Devi.", director: "Ajoy Kar" },
  "trijama-1956": { wikiTitle: "Trijama", extract: "Trijama (English: Three Facets) is a 1956 Indian Bengali romantic drama film directed by Agradoot, based on Subodh Ghosh's novel of the same name. This film was released under the banner of Sunrise Films. Music direction of the film was made by Nachiketa Ghosh.", director: "Agradoot" },
  "putrabadhu-1956": { wikiTitle: "Putrabadhu", extract: "Putrabadhu (lit. 'Daughter-in-law') is a 1998 Bengali film directed by Pallab Ghosh and Chief assistant director was Madhuchhanda Sengupta and produced under the banner of Damini Pictures Pvt. Ltd. The film is a remake of National Award winning 1986 Tamil film Samsaram Adhu Minsaram by Visu.", director: "Pallab Ghosh" },
  "bardidi-1957": { wikiTitle: "Bardidi", extract: "Bardidi is a Bengali drama film directed by Ajoy Kar, based on the novel of the same name by Sarat Chandra Chattopadhyay. This film was released in 1957 under the banner of Sarat Banichitra.", director: "Ajoy Kar" },
  "tasher-ghar-1957": { wikiTitle: "Tasher Ghar", extract: "Tasher Ghar (Bengali pronunciation: [taser ɡʰor] transl. House of Cards) is a 1957 Indian Bengali action drama film co-written and directed by Mangal Chakraborty in his directorial debut. Produced by Govind Chand Burman under the banner of National Films, the film stars Uttam Kumar in dual roles, alongside Sabitri Chatterjee and Sabita Bose in lead roles, with Tarun Kumar, Chandrabati Devi, Rabin Majumder, and Jahar Ganguly in supporting roles. Based on a story by Rashbehari Lal, which shows traces of influence from Daphne Du Maurier’s 1957 novel The Scapegoat." },
  "punarmilan-1957": { wikiTitle: "Punar Milan", extract: "Punar Milan is a 1940 Bollywood film directed by Najam Naqvi and written by Saradindu Bandopadhyay. Kishore Sahu and Snehprabha Pradhan played the lead roles in the movie.", director: "Najam Naqvi" },
  "harano-sur-1957": { wikiTitle: "Harano Sur", extract: "Harano Sur (Bengali pronunciation: [harano sur]; transl. The Lost Tune) is a 1957 Indian Bengali psychological romantic drama film directed by Ajoy Kar. Produced by Uttam Kumar under his home-banner of Alo Chhaya Productions, the film is an adaptation of the 1942 American film Random Harvest, which itself is based on James Hilton's eponymous novel. It stars Kumar himself alongside Suchitra Sen, with a supporting cast including Pahari Sanyal, Utpal Dutt, Chandrabati Devi and Kajari Guha.", director: "Ajoy Kar" },
  "chandranath-1957": { wikiTitle: "Chandranath (1957 film)", extract: "Chandranath (English: Chandranath) is a 1957 Indian Bengali language romantic drama film under the banner of Screen Classics Private Ltd. It was directed by Kartik Chatterjee, and the music was composed by Robin Chatterjee. The film is based on Sarat Chandra Chatterjee's novel of same name and starring Uttam Kumar in title role with Suchitra Sen in lead and others like Chabi Biswas, Tulsi Chakraborty, and Chandrabati Devi in supporting role.", director: "Kartik Chatterjee" },
  "pathey-holo-deri-1957": { wikiTitle: "Pathey Holo Deri", extract: "Pathey Holo Deri is a 1957 Bengali romantic drama film directed by Agradoot. The film's music was composed by Robin Chatterjee. The film stars Uttam Kumar, and Suchitra Sen in leading role and others artists like Shishir Batabyal, Anil Bhattacharya, Mihir Bhattacharya, Chhabi Biswas, Bharati Devi, Chandrabati Devi, Jahar Ganguli, Anup Kumar, Shyam Laha, Gopal Majumdar, Chitra Mandal, Sova Sen, and Kamala Mukherjee in the supporting roles.", director: "Agradoot" },
  "jiban-trishna-1957": { wikiTitle: "Jiban Trishna", extract: "Jiban Trishna (; English: Thirst for Life) is a 1957 Indian Bengali drama film directed and screenplay written by the famous director Asit Sen. The story of the film was written by Ashutosh Mukherjee. This film is made under the banner of Badal Pictures." },
  "bandhu-1958": { wikiTitle: "Bandhu", extract: "Bandhu (1), Sanskrit for friend, connected with bandhana or ties, which are the connections that, according to the Vedas, link the outer and the inner worlds. Vedic texts speak, for example, of the 360 bones of the fetus that fuse into the 206 bones of the adult (after the 360 days of the year). As per Dharma traditions, 'Bandhutva' exists in all planes/fields, connecting them together." },
  "rajlakshmi-o-srikanta-1958": { wikiTitle: "Rajlakshmi O Srikanta", extract: "Rajlakshmi O Srikanta is a 1958 Bengali drama film directed by Haridas Bhattacharya and produced by Kanan Devi based on the iconic and famous novel Srikanta of the legendary Sarat Chandra Chattopadhyay. This film was released in 1958 under the banner of Srimati Pictures. Music direction of the film was done by Jnan Prakash Ghosh.", director: "Haridas Bhattacharya" },
  "manmoyee-girls-school-1958": { wikiTitle: "Manmoyee Girls' School", extract: "Manmoyee Girls' School is a 1935 Indian Bengali romantic comedy film directed by Jyotish Bannerjee under the banner of Radha Films Company. It is based on Rabindranath Maitra's 1932 play of the same name. The film stars Tulsi Chakraborty, Jahar Ganguly and Kanan Devi.", director: "Jyotish Bannerjee" },
  "indrani-1958": { wikiTitle: "Indrani (film)", extract: "Indrani is a Bengali romantic drama film directed by Niren Lahiri based on a story of Achintya Kumar Sengupta. This film was released in 1958 under the banner of H.N.C. Productions. Nachiketa Ghosh was the music director of the movie.", director: "Niren Lahiri" },
  "marutirtha-hinglaj-1959": { wikiTitle: "Marutirtha Hinglaj", extract: "Marutirtha Hinglaj (English: Hinglaj, the Desert Shrine) is a 1959 Indian Bengali drama film directed and produced by Bikash Roy. This was based on a same name travelogue of Bengali novelist Kalikananda Abadhuta. The film was made under the banner of Bikash Roy Productions and Janata Pictures and Theatres Limited." },
  "chaowa-paowa-1959": { wikiTitle: "Chaowa Pawa (1959 film)", extract: "Chaowa Pawa (transl. Desires and Fulfilment) is a 1959 Indian Bengali romantic comedy film directed by three directors Sachin Mukherjee, Dilip Mukherjee, and Tarun Majumdar. It is based on the 1934 Academy Awards winning American film It Happened One Night. The film stars Uttam Kumar and Suchitra Sen in lead roles." },
  "bicharak-1959": { wikiTitle: "Bicharak", extract: "Bicharak (English: The Judge) is a 1959 Bengali psychological thriller film directed by Prabhat Mukherjee. Based on a novel of the same name by Tarasankar Bandyopadhyay, the film was produced by Arundhati Devi. It was released under the banner of Prabhat Productions and received National Film Award for Best Feature Film in Bengali in 1960.", director: "Prabhat Mukherjee" },
  "sonar-harin-1959": { wikiTitle: "Sonar Harin", extract: "Sonar Harin (transl. The Golden Deer) is a 1959 Indian Bengali spy action-thriller film co-written and directed by Mangal Chakravarty. This film was written by Rashbehari Lal. The production company for this film is National Pictures.", director: "Mangal Chakravarty" },
  "abak-prithibi-1959": { wikiTitle: "Abak Prithibi", extract: "Abak Prithibi is a 1959 Bengali film directed by Bishu Chakraborty. This film was produced by Tarun Kumar, who was also a Bengali film actor. This film was written by Bishu Chakraborty.", director: "Bishu Chakraborty" },
  "maya-mriga-1960": { wikiTitle: "Maya Mriga", extract: "Maya Mriga is a 1960 Indian Bengali film directed by Chitta Bose. This film was released under the banner of MKG Private Production Limited. The film stars Uttam Kumar, Sandhya Roy and Biswajit Chatterjee.", director: "Chitta Bose" },
  "kuhak-1960": { wikiTitle: "Kuhak (1960 film)", extract: "Kuhak is a 1960 Bengali action thriller film directed by Agradoot and starring Uttam Kumar and Sabitri Chatterjee in lead roles. This film portrays a man's struggle to run blindly after riches.", director: "Agradoot" },
  "uttar-megh-1960": { wikiTitle: "Uttar Megh", extract: "Uttar Megh is a 1960 Bengali film directed by Jiban Ganguly. This is a drama film. This film was released on 12 January 1960.", director: "Jiban Ganguly" },
  "khokababur-pratyabartan-1960": { wikiTitle: "Khokababur Pratyabartan", extract: "Khokababur Pratyabartan (English: The Return of Little Master) is a 1960 Indian Bengali social drama film directed by Agradoot based on the 1891 short story of the same name by Rabindranath Tagore. The film stars Uttam Kumar in the lead with Asit Baran, Sumita Sanyal and others in supporting role. This film was released on 28 April 1960 under the banner of Agradoot Chitra.", director: "Agradoot" },
  "sathi-hara-1961": { wikiTitle: "Sathi Hara", extract: "Sathi Hara is a Bengali romantic drama film directed by Sukumar Dasgupta produced by Rakhal Chandra Saha. This film was released on 2 March 1961. Renowned author and filmmaker Premendra Mitra served as the script writer of the film." },
  "jhinder-bondi-1961": { wikiTitle: "Jhinder Bondi", extract: "Jhinder Bondi (Bengali pronunciation: [dʒʱindeɾ bondi] transl. Prisoner of Jhind) is a 1961 Indian Bengali epic period action-adventure film co-written and directed by Tapan Sinha. Produced by Bholanath Roy under his banner B. N. Productions, the film was based on Saradindu Bandyopadhyay's novel of the same name, which itself was adapted from the 1894 novel The Prisoner of Zenda by Anthony Hope. It stars Uttam Kumar in triple roles, alongside an ensemble cast of Soumitra Chatterjee, Arundhati Devi, Tarun Kumar, Dilip Roy, Radhamohan Bhattacharya and Sandhya Roy in lead roles.", director: "Tapan Sinha" },
  "saptapadi-1961": { wikiTitle: "Saptapadi (1961 film)", extract: "Saptapadi (transl. Seven Steps) is a 1961 Indian Bengali epic romantic drama film by Ajoy Kar, starring Suchitra Sen, Uttam Kumar, Chhabi Biswas and Chhaya Debi. Music direction and playback singing for Kumar's voice was by Hemanta Mukherjee and in Sen's voice by Sandhya Mukherjee. The story is based on a 1958 same name novel by Tarasankar Bandyopadhyay." },
  "bipasha-1962": { wikiTitle: "Bipasha (film)", extract: "Bipasha is a 1962 Indian Bengali drama film starring Uttam Kumar and Suchitra Sen. and directed by Agradoot. The film is based on a novel titled Bipasha by Sri Tarashankar Bandyopadhay.The story fleetingly describes the horror of riots in West Pakistan during the time of Partition of India.", director: "Agradoot" },
  "shiulibari-1962": { wikiTitle: "Shiulibari", extract: "Shiulibari is a 1962 Bengali drama film starring Uttam Kumar and Arundhati Devi. The film was released under the banner of Movietalk Private Limited, directed by Pijush Bose and the screenplay was by the legendary Tapan Sinha. The story was written by Subodh Ghosh and music was composed by Arundhati himself.", director: "Pijush Bose" },
  "shes-anko-1963": { wikiTitle: "Sesh Anka", extract: "Sesh Anka (transl. The final act) is a 1963 Indian Bengali thriller film directed by Haridas Bhattacharya and made by Kalpana Movies, Kolkata. This film was loosely inspired by the 1958 film Chase a Crooked Shadow. The film starred Uttam Kumar in lead with Sharmila Tagore, Sabitri Chatterjee, Pahadi Sanyal, Bikash Roy, Kamal Mitra and others in supporting role.", director: "Haridas Bhattacharya" },
  "uttarayan-1963": { wikiTitle: "Uttarayan (1963 film)", extract: "Uttarayan (Bengali pronunciation: [ut̪ːɔrajaɳ]) is a 1963 Indian Bengali war drama film co-written and directed by Agradoot. Produced by Parashmal Bhuteria and Deepchand Kankariya under the banner of Parashmal–Deepchand Ventures, the film is based Tarashankar Bandyopadhyay's short story of the same name and is also heavily inspired by its Hindi screen adaptation Hum Dono (1961) starring Dev Anand. The film stars Uttam Kumar in dual roles, alongside Supriya Devi, Sabitri Chatterjee and Anil Chatterjee in another pivotal roles.", director: "Agradoot" },
  "bhranti-bilas-1963": { wikiTitle: "Bhranti Bilas", extract: "Bhranti Bilash (transl. Comedy of Errors) is a 1963 Indian Bengali action comedy film directed by Manu Sen. Produced by Uttam Kumar under his banner of Uttam Kumar Films, the film is based on the 1869 play of the same name by Ishwar Chandra Vidyasagar, which is itself is an adaptation of William Shakespeare's The Comedy of Errors. It stars Kumar himself and Bhanu Bandopadhyay, both in dual roles, alongside Sabitri Chatterjee, Sandhya Roy, Chhaya Devi and Sabita Bose in another pivotal roles.", director: "Manu Sen" },
  "deya-neya-1963": { wikiTitle: "Deya Neya", extract: "Deya Neya (English: The Exchange, released 1963) is a Bengali musical drama film directed by Sunil Bandopadhyay and starring Uttam Kumar and Tanuja in lead roles. This is a romantic comedy film which portrays a man's struggle on a light note and ends with a happy ending. The film was produced and composed by Shyamal Mitra.", director: "Sunil Bandopadhyay" },
  "surya-sikha-1963": { wikiTitle: "Surya Sikha", extract: "Surya Sikha (transl. The Sun Flame) is a Bengali romance drama film directed by Salil Dutta. This film was released on 12 July 1963 under the banner of Chhayachhabi Pratisthan. The film stars Uttam Kumar and Supriya Debi in lead roles and Chabi Biswas, Utpal Dutta and others played supporting role.", director: "Salil Dutta" },
  "bibhas-1964": { wikiTitle: "Bibhas", extract: "Bibhas is a Hindustani classical raga." },
  "jatugriha-1964": { wikiTitle: "Jatugriha", extract: "Jatugriha is a 1964 Indian Bengali drama film directed by Tapan Sinha and produced by Uttam Kumar based on the novel of the same name by Subodh Ghosh. The film was produced and released on 20 March 1964 under the banner of Uttam Kumar Films Private Limited. The music was composed by the legendary Ashish Khan.", director: "Tapan Sinha" },
  "momer-alo-1964": { wikiTitle: "Momer Alo", extract: "Momer Alo is a 1964 Bengali drama film directed by Salil Dutta. The film stars Uttam Kumar and Sabitri Chatterjee in lead roles. It has music composed by Robin Chatterjee.", director: "Salil Dutta" },
  "lal-pathore-1964": { wikiTitle: "Lal Pathore", extract: "Lal Pathore (Bengali pronunciation: [lal paθor] transl. The Red Stone) is a 1964 Indian Bengali period action drama film co-written and directed by Sushil Majumder. Produced by Subhas Ranjan Basu under the banner of Esarby Productions, the film stars Uttam Kumar, Supriya Devi, Nirmal Kumar and Srabani Basu in lead roles, while Rabi Ghosh, Raja Mukherjee, Mani Srimani and Majumder himself play another pivotal roles. Based on a story by Prashanta Chowdhury, the film follows the transformation of a light-hearted king into an arrogant, when he becomes obsessed with a girl younger than him, because of a curse regarding his royal ancestors.", director: "Sushil Majumder" },
  "thana-theke-aaschhi-1965": { wikiTitle: "Thana Theke Aschi (1965 film)", extract: "Thana Theke Aschhi (English: Coming From Police Station) is a 1965 Indian Bengali psychological thriller film co-written and directed by Hiren Nag. Produced by Hemen Mitra, Tapas Saha and Ratan Chakraborty under the banner of United Cine Producers, it was based on a play of the same name by Ajit Gangopadhyay, which itself was an adaptation of the English play An Inspector Calls (1945) by J. B. Priestley. The film stars Uttam Kumar, Madhabi Mukherjee and Anjana Bhowmick in the lead, while Kamal Mitra, Chhaya Debi, Dilip Mukherjee, Prashanta Kumar and Jahor Roy play another pivotal roles.", director: "Hiren Nag" },
  "rajkanya-1965": { wikiTitle: "Rajkanya (bengali film 1965)", extract: "Rajkanya (English: Princess) is a 1965 Bengali film directed by Sunil Bandyopadhyay. The movie was based on a story and screenplay by legendary film director Ritwik Ghatak. Uttam Kumar, Rina Ghosh, Bhanu Bandopadhyay, and Tarun Kumar portray the main characters.", director: "Sunil Bandyopadhyay" },
  "rajodrohi-1966": { wikiTitle: "Rajodrohi", extract: "Rajodrohi (Bengali pronunciation: [rad͡ʒd̪rohi] transl. The Royal Rebel) is a 1966 Indian Bengali vigilante action film directed by Niren Lahiri. Produced by B. K. Ahuja under the banner of B. K. Productions, it stars Uttam Kumar and Anjana Bhowmick in lead roles, alongside Bikash Roy, Kamal Mitra, Anup Kumar, Dilip Roy and Tarun Kumar in another pivotal roles. The film portrays a farmer who transforms into a vigilante to take revenge from his mother's assassins.", director: "Niren Lahiri" },
  "shudhu-ekti-bachhar-1966": { wikiTitle: "Shudhu Ekti Bachhar", extract: "Sudhu Ekti Bochor is a 1966 Indian Bengali romantic drama film starring Uttam Kumar and Supriya Devi with screenplay directed by Uttam himself. The music was composed by Robin Chatterjee. The story was written by Gauriprasanna Mazumder, who also wrote the lyrics." },
  "nayak-1966": { wikiTitle: "Nayak (1966 film)", extract: "Nayak (subtitled as The Hero; Bengali pronunciation: [naːok]) is a 1966 Indian Bengali epic psychological drama written, scored and directed by Satyajit Ray. Produced by R. D. Bansal under the banner of R. D. B. & Co., the film stars Uttam Kumar as a matinee idol on a 24-hour train ride from Kolkata to Delhi to receive a National Award, where he ends up revealing his mistakes, insecurities, and regrets during a multi-part interview to a young journalist, played by Sharmila Tagore.\nWritten and filmed in 1965, Nayak is Ray's second entirely original screenplay, after Kanchenjungha (1962).", director: "Satyajit Ray" },
  "chhoti-si-mulaqat-1967": { wikiTitle: "Chhoti Si Mulaqat", extract: "Chhoti Si Mulaqat (English: A Brief Interaction) is a 1967 Indian Hindi-language romantic drama film directed by Alo Sarkar starring Uttam Kumar and Vyjayanthimala. It's a remake of 1954 Bengali film Agni Pariksha directed by Agradoot which was an adaption of Asha Purna Devi's novel of the same name.", director: "Alo Sarkar" },
  "nayika-sangbad-1967": { wikiTitle: "Nayika Sangbad", extract: "Nayika Sangbad (transl. News About the Heroine) is a 1967 Indian Bengali romantic comedy film directed by Agradoot and written by Prasanta Deb. The film stars Uttam Kumar and Anjana Bhowmick. It was remade in Tamil as Sumathi En Sundari (1971).", director: "Agradoot" },
  "chiriyakhana-1967": { wikiTitle: "Chiriyakhana", extract: "Chiriakhana or Chiriyakhana (English: The Menagerie) is a 1967 Indian Bengali crime thriller film, based on the story of the same name by Sharadindu Bandyopadhyay. The film is directed and co-written by Satyajit Ray, starring Uttam Kumar as Byomkesh Bakshi." },
  "antony-firingee-1967": { wikiTitle: "Antony Firingee (film)", extract: "Antony Firingee is a 1967 Indian Bengali biographical musical drama film written and directed by Sunil Bannerjee. Produced by Bholanath Roy under the banner of B. N. Roy Productions, it stars Uttam Kumar and Tanuja on the lead. It is a biopic based on the life of Anthony Firingee (Hensman Anthony), a Bengali language folk poet of Portuguese origin.", director: "Sunil Bannerjee" },
  "chowringhee-1968": { wikiTitle: "Chowringhee (film)", extract: "Chowringhee is a 1968 Indian Bengali drama film by Pinaki Bhushan Mukherjee, starring Uttam Kumar and Subhendu Chatterjee who played the lead role and Biswajit Chatterjee, Supriya Devi and Anjana Bhowmick in supporting role. The music of the film was composed by Ashima Bhattachariya who also produced this film. The film is based on a Bengal novel of the same name by Sankar." },
  "gar-nasimpur-1968": { wikiTitle: "Gar Nasimpur", extract: "Garh Nasimpur is a 1968 Indian Bengali language historical action film directed by Ajit Lahiri. The film was released under the banner of Shadow Productions in 1968 and its music was directed by Shyamal Mitra. The film stars Uttam Kumar, Biswajit Chatterjee, Madhavi Mukherjee, and Ruma Guhathakurta.", director: "Ajit Lahiri" },
  "kokhono-megh-1968": { wikiTitle: "Kokhono Megh", extract: "Kokhono Megh is a 1968 Bengali black comedy action thriller film directed by Agradoot. Produced by Bibhuti Laha and Shiv Narayan Dutta under the banner of Chalacchitra Bharati in their second production, the film is loosely inspired by the Cary Grant starrer American film Charade (1963). It stars Uttam Kumar, Anjana Bhowmik and Kali Banerjee in lead roles.", director: "Agradoot" },
  "aparichita-1969": { wikiTitle: "Aparichita (1969 film)", extract: "Aparichita is a 1969 Indian Bengali thriller film co-written and directed by Salil Dutta. Produced by Debnath Roy and Geetali Dutta under the banner of R. D. Productions, the film is based on the novel of the same name by Samaresh Basu, which itself was actually inspired by The Idiot written by Fyodor Dostoyevsky. It stars Uttam Kumar, Soumitra Chatterjee, Sandhya Roy, and Aparna Sen in the lead, while Utpal Dutt, Bikash Roy, Tarun Kumar, Dilip Roy and Haradhan Bandyopadhyay in another pivotal roles.", director: "Salil Dutta" },
  "bilambita-loy-1970": { wikiTitle: "Bilambita Loy", extract: "Bilambita Loy (/biˈlʌm.bɪ.toʊ lɔɪ/ transl. The Delayed Rhythm) is a 1970 Indian Bengali drama film co-written and directed by Agragami. Produced by Ajoy Basu and Anil Shah under the banner of Anuradha Films, the film is based on a story by Narendranath Mitra. Also inspired by the 1954 version of A Star Is Born, it stars Uttam Kumar, Supriya Devi and Shyamal Ghoshal.", director: "Agragami" },
  "rajkumari-1970": { wikiTitle: "Rajkumari (1970 film)", extract: "Rajkumari (Bengali pronunciation: [rad͡ʒkumari] transl. Princess) is a 1970 Indian Bengali masala film written and directed by Salil Sen. Produced by Debesh Ghosh and Ranjana Ghosh under the banner of Loknath Chitramandir, the film stars Uttam Kumar and Tanuja in lead roles, while Chhaya Devi, Pahari Sanyal, Bhanu Banerjee, Jahar Roy, Dipti Roy and Tarun Kumar play another supporting roles, with Helen in a guest appearance. The film plots a princess Manju, confined to the rules under his mother's supervision, falling in love with an insurance agent Nirmal, while things get unexpected when Nirmal meets with an accident and loses his eyesight, on the wedding day.", director: "Salil Sen" },
  "nishi-padma-1970": { wikiTitle: "Nishi Padma", extract: "Nishi Padma (Bengali pronunciation: [ˈniʃi ˈpəd̪ma] transl. The Night-Lotus) is a 1970 Indian Bengali drama film co-written and directed by Arabinda Mukhopadhyay. Produced by Shantimoy Banerjee under the banner of Chirantan Chitra, the film is based on Bibhutibhushan Bandopadhyay's short story Hinger Kochuri. The film portrays the decline of human values and relationships and contrasts it by presenting an illustrious example of a boy's innocent love for a neighbourhood tawaif (courtesan).", director: "Arabinda Mukhopadhyay" },
  "ekhane-pinjar-1971": { wikiTitle: "Ekhane Pinjar", extract: "Ekhane Pinjar is a Bengali crime drama film directed by Tarun Majumder (Yatrik) based on the novel of Prafulla Roy. The film was released on 22 January 1971 under the banner of Mitali Films. The music director of this film was Bhupen Hazarika." },
  "dhanyee-meye-1971": { wikiTitle: "Dhanyee Meye", extract: "Dhanyee Meye is a 1971 Bengali sports action comedy film directed by Arabinda Mukhopadhyay. The cast includes Uttam Kumar, Sabitri Chatterjee, Partho Mukherjee, Jaya Bhaduri, Jahor Roy and Nripati Chattopadhyay. This was Bhaduri's third film overall and only her second Bengali film.", director: "Arabinda Mukhopadhyay" },
  "jay-jayanti-1971": { wikiTitle: "Jay Jayanti", extract: "Jay Jayanti is a 1971 Indian Bengali children's musical film directed by Sunil Basu Mullick in his directorial debut. Produced by his wife Bhabani Basu Mullick under the banner of M. K. G. Productions Pvt. Ltd., the film stars Aparna Sen as Jayanti who joins the wealthy Roy family as a governess, wins over the five children, and eventually earns the respect of their stern uncle Sanjoy, played by Uttam Kumar." },
  "chhadmabeshi-1971": { wikiTitle: "Chhadmabeshi", extract: "Chhadmabeshi (Bengali pronunciation: [tʃʰɔd̪mabɛʃi] transl. Disguiser) is a 1971 Bengali comedy film directed by Agradoot. Produced by Bibhuti Laha and Shib Narayan Dutta under the banner of Chalacchitra Bharati in their second production, the film stars Uttam Kumar and Madhabi Mukherjee, alongside an ensemble cast of Subhendu Chatterjee, Bikash Roy, Tarun Kumar, Anubha Gupta, Jyotsna Biswas, Shamita Biswas and Jahor Roy in another pivotal roles.\nBased on a story of the same name by Upendranath Ganguly, the film revolves around a newly married professor, who plays a practical joke upon his brother-in-law by posing as his family driver.", director: "Agradoot" },
  "andha-atit-1972": { wikiTitle: "Andha Atit", extract: "Andha Atit (transl. Blind Past) is a 1972 Indian Bengali crime action film written and directed by Hiren Nag. The film was produced by Asim Sarkar under the banner of Usha Films, starring Uttam Kumar and Supriya Devi in lead roles.", director: "Hiren Nag" },
  "stree-1972": { wikiTitle: "Stree (1972 film)", extract: "Stree is a 1972 Indian Bengali period action drama film directed by Salil Dutta. The film is based on the novel of Bimal Mitra by the same title and the era of the plot showing during the Second World War. Produced by Baby June Productions marking their second venture, it stars Uttam Kumar, Soumitra Chatterjee and Arati Bhattacharya in lead roles.", director: "Salil Dutta" },
  "mem-saheb-1972": { wikiTitle: "Mem Saheb", extract: "Mem Saheb is a 1972 Bengali film directed by Pinaki Mukherjee who also acts in this film. The film was produced by Ashima Bhattacharya and production company by Pompy Films. The story was based on the novel of same name by Nimai Bhattachariya." },
  "bon-palashir-padabali-1973": { wikiTitle: "Bon Palashir Padabali", extract: "Bon Palashir Padabali is a 1973 Indian Bengali language romantic action drama film co-written and directed by Uttam Kumar. It is an adaptation of a 1960 same name novel by Ramapada Chowdhury. The film was released on 9 February 1973, under the banner of Uttam foundation Shilpi Sangsad.", director: "Uttam Kumar" },
  "kayahiner-kahini-1973": { wikiTitle: "Kayahiner Kahini", extract: "Kayahiner Kahini (transl. The Tale of an Incorporeal) is a 1973 Indian Bengali supernatural psychological horror film co-written and directed by Ajoy Kar. Produced by Mukul Roy under the banner of Mukul Roy Productions, the film stars Uttam Kumar in dual roles, alongside an ensemble cast of Aparna Sen, Bikash Roy, Pahari Sanyal, Tarun Kumar and Basabi Nandi.\nBased on Nabendu ghosh's short story Asharirini, the film depicts on a writer who gets trapped into a mysterious situation regarding supernatural events due to his resemblance to a wealthy businessman.", director: "Ajoy Kar" },
  "sonar-khancha-1973": { wikiTitle: "Sonar Khancha", extract: "Sonar Khancha (transl. Golden Cage) is a 1973 Bengali masala film that was directed by Agradoot Music of the film was composed by Bireshwar Sarkar. Uttam Kumar, Aparna Sen and Tarun Kumar played the lead roles.", director: "Agradoot Music" },
  "jadi-jantem-1974": { wikiTitle: "Jadi Jantem", extract: "Jadi Jantem (English: If I Knew) is a 1974 Indian Bengali detective action thriller film directed by Tarun Majumdar as Yatrik. This movie was released under the banner of Chitrajug. Uttam Kumar played the main protagonist of the movie, Mr." },
  "jadu-bansha-1974": { wikiTitle: "Jadu Bansha", extract: "Jadu Bansha is a Bengali political drama film directed by Partha Pratim Chowdhury based on a story of Bengali author Bimal Kar. The film was released in 1974 under the banner of Montage Films.", director: "Partha Pratim Chowdhury" },
  "amanush-1974": { wikiTitle: "Amanush (1975 film)", extract: "Amanush (Bengali pronunciation: [əˈmɑːnuʃ]; transl. Inhuman) is a 1974 Indian action drama film, simultaneously shot in Bengali and Hindi languages, produced and directed by Shakti Samanta under his banner of Shakti Films. Based on Shaktipada Rajguru's story Naya Basat, the film stars Uttam Kumar in the titular role, alongside Sharmila Tagore, Utpal Dutt and Anil Chatterjee, while Prema Narayan, Abhi Bhattacharya, Amarnath Mukherjee and Asit Sen play other pivotal roles, with Shambhu Bhattacharya in a special appearance. The film follows Madhu, who transforms into a penniless drunkard from a scion of a landlord family, after getting implicated in a false murder case by a vindictive man.", director: "Shakti Samanta" },
  "mouchak-1975": { wikiTitle: "Mouchak", extract: "Mouchak is a Bengali romantic comedy film directed by Arabinda Mukhopadhyay. The film stars Uttam Kumar, Sabitri Chatterjee, Ranjit Mullick, Mithu Mukherjee, Sulata Chowdhury, Ratna Ghoshal, and Nripati Chattopadhyay in lead roles. Nachiketa Ghosh scored the music in the film.", director: "Arabinda Mukhopadhyay" },
  "ami-shey-o-shakha-1975": { wikiTitle: "Ami, Shey O Shakha", extract: "Ami, Shey O Shakha (Bengali pronunciation: [ami, ʃe o ʃakʰa] transl. Me, Him and Our Friend) is a 1975 Indian Bengali drama film co-written and directed by Mangal Chakravarty. Produced by Shyamal Mitra and Deepen Bhattacharya under the banner of S. D. Productions, the film is based on a novel of the same name by Ashutosh Mukhopadhyay. It stars Uttam Kumar in dual roles, alongside Anil Chatterjee, Arati Bhattacharya and Kaberi Bose in lead roles.", director: "Mangal Chakravarty" },
  "agnishwar-1975": { wikiTitle: "Agnishwar", extract: "Agnishwar (English: The fire god) is a 1975 Indian Bengali language socio-political drama film co-written and directed by Arabinda Mukhopadhyay. The story of the film is based on the novel of the same name written by Balai Chand Mukhopadhyay, which itself was inspired from the life of his teacher Banabihari Mukhopadhyay. it stars Uttam Kumar in the titular role, alongside Madhabi Chakraborty, Sumitra Mukherjee, Kajal Gupta, Partha Mukherjee in lead roles, while Tarun Kumar, Dilip Roy, Asit Baran, Jahar Roy, Haridhan Mukhopadhyay play other pivotal roles.", director: "Arabinda Mukhopadhyay" },
  "priyo-bandhabi-1975": { wikiTitle: "Priyo Bandhabi", extract: "Priyo Bandhabi is a 1975 Bengali romantic comedy film directed by Hiren Nag. This film was written by Prabodh Kumar Sanyal. The film's music was composed by Nachiketa Ghosh.", director: "Hiren Nag" },
  "sanyasi-raja-1975": { wikiTitle: "Sanyasi Raja", extract: "Sanyasi Raja (transl. The Monk King) is a 1975 Indian Bengali period action drama film written and directed by Pijush Basu. Produced by Asim Sarkar under the banner of Usha Films, the film is based on the real life incident of the Bhawal case. It stars Uttam Kumar in the title role alongside Supriya Devi in lead roles.", director: "Pijush Basu" },
  "bagh-bondi-khela-1975": { wikiTitle: "Bagh Bondi Khela", extract: "Bagh Bondi Khela (transl. The Caged Tiger Game) is a 1975 Indian Bengali political action thriller film co-written and directed by Pijush Basu. Produced by Ashima Bhattacharya, the film is based on Prafulla Roy's novel titled Prothom Tarar Alo. It stars Uttam Kumar, Supriya Devi, Partha Mukherjee and Mahua Roy Chowdhury in lead roles, while Tarun Kumar, Asit Baran, Tarun Mitra and Kalyani Mondal play supporting roles.", director: "Pijush Basu" },
  "sei-chokh-1976": { wikiTitle: "Sei Chokh", extract: "Sei Chokh is a Bengali masala film directed by Salil Dutta based on a story by Bengali novelist Bimal Mitra. The film was released on 30 July 1976 under the banner of Gitali Pictures. Nachiketa Ghosh was the music director of Sei Chokh.", director: "Salil Dutta" },
  "nidhiram-sardar-1976": { wikiTitle: "Nidhiram Sardar", extract: "Nidhiram Sardar (Bengali pronunciation: [nidhiɾam sɔrdɑr]) is a 1976 Indian Bengali vigilante action film directed by Rabi Ghosh in his debut. Produced by Deepen Bhattacharya under the banner of Subhadeep Chitram, the film stars Uttam Kumar in the titular role, alongside Aparna Sen, Utpal Dutt, Subhendu Chatterjee, Tarun Kumar and Ajitesh Banerjee in other pivotal roles.\nWritten by Ashok Ghoshal, the film drew inspirations from the folklores of Robin Hood, while Ghosh himself cited the film as a felicitation to Wolfshead (1969) and Magnum Force (1973)." },
  "rajbansha-1977": { wikiTitle: "Rajbansha", extract: "Rajbansha (Bengali pronunciation: [rad͡ʒbɔŋʃo]; transl. Dynasty) is a 1977 Indian Bengali action film written and directed by Pijush Basu. Produced by Asim Sarkar under the banner of Usha Films, the film stars Uttam Kumar in dual roles, alongside Arati Bhattacharya, Prema Narayan, Bikash Roy, Dilip Roy and Chhaya Devi in other pivotal roles. It focuses on Bhairav Narayan, the king of the Mainabati Estate, who refuses to acknowledge his illegitimate son Pratap Narayan as his own child and a member of the royal dynasty, which leads the latter to become utterly psychotic and to murder his father in retaliation for the humiliation inflicted upon his mother.", director: "Pijush Basu" },
  "sabyasachi-1977": { wikiTitle: "Sabyasachi (film)", extract: "Sabyasachi is a 1977 Bengali language period political action thriller film directed by Pijush Basu. Based on the novel Pather Dabi written by Sarat Chandra Chattopadhyay, the film produced by Asim Sarkar under the banner of Usha Films. It stars Uttam Kumar in the titular role, alongside Supriya Devi, Bikash Roy, Kiran Lahiri and Tarun Kumar in lead roles.", director: "Pijush Basu" },
  "jaal-sannyasi-1977": { wikiTitle: "Jaal Sannyasi", extract: "Jaal Sannyasi is a Bengali drama film directed by Salil Sen based on the novel Muktisnan of Charu Chandra Bandopadhyay. This film was released on 26 August 1977 under the banner of Usha Films. The music director of the movie was Shyamal Mitra.", director: "Salil Sen" },
  "ananda-ashram-1977": { wikiTitle: "Anand Ashram", extract: "Ananda Ashram (Hindi: Anand Ashram, English: The Ashram of joy) is a 1977 Indian bilingual romantic drama film made in Bengali and Hindi language simultaneously, co-written and directed by Shakti Samanta. Based on a story by film director and novelist, Sailajananda Mukhopadhyay, it stars Ashok Kumar, Uttam Kumar, Sharmila Tagore, Moushumi Chatterjee and Rakesh Roshan (making his debut in Bengali cinema) in lead roles. The same story was earlier filmed as 'Doctor' in 1940 starred by Pankaj Mullick, Ahindra Choudhury and Bharati Devi.", director: "Shakti Samanta" },
  "kitaab-1977": { wikiTitle: "Kitaab", extract: "Kitaab (English: The Book) is a 1977 Indian drama film written and directed by Gulzar. The film stars Uttam Kumar, Vidya Sinha, Shreeram Lagoo, Keshto Mukherjee and Asit Sen. The film was based on Bengali story Pathik by Samaresh Basu.", director: "Gulzar" },
  "dui-purush-1978": { wikiTitle: "Dui Purush (1978 film)", extract: "Dui Purush is a 1978 Bengali action drama film directed by Sushil Mukhopadhyay. The film's music was composed by Kalipada Sen.", director: "Sushil Mukhopadhyay" },
  "bandie-1978": { wikiTitle: "Bandie", extract: "Bandie is a 1978 Indian bilingual swashbuckler action film simultaneously shot in Bengali and Hindi languages, co-written and directed by Alo Sircar. Produced by F. C. Mehra under the banner of Eagle Films, the film stars Uttam Kumar in dual roles, alongside an ensemble cast of Utpal Dutt, Amjad Khan, Sulakshana Pandit, Amrish Puri, Bindu, Iftekhar, Madan Puri and Prema Narayan, with Helen and Padma Khanna in special appearances.\nThe film is partially adapted from Anthony Hope's 1894 novel The Prisoner of Zenda, and had some plot similarities with the 1961 Bengali film Jhinder Bondi, also starring Kumar.", director: "Alo Sircar" },
  "nishan-1978": { wikiTitle: "Nishan (1978 film)", extract: "Nishan is a Bengali language swashbuckler film directed by S.S. Balan. This film was released on 4 August 1978 under the banner of Gemini Production Circuit Private Limited.", director: "S.S. Balan" },
  "dhanraj-tamang-1978": { wikiTitle: "Dhanraj Tamang", extract: "Dhanraj Tamang is a 1978 Indian Bengali vigilante action film co-written and directed by Pijush Basu. Produced by Asim Sarkar under the banner of Usha Films, the film is based on a story by Charuchandra Chakraborty. It stars Uttam Kumar in the titular role, alongside Sandha Roy, Utpal Dutt, Anil Chatterjee, Dilip Roy and Chhaya Devi in lead roles.", director: "Pijush Basu" },
  "devdas-1979": { wikiTitle: "Devdas (1979 film)", extract: "Devdas (Debdash) is a 1979 a Bengali epic period drama film based on Sarat Chandra Chattopadhyay's 1917 novel Devdas. The film stars Soumitra Chatterjee, Uttam Kumar, Sumitra Mukherjee, and Supriya Choudhury. The lyrics for the film's songs were written by Kazi Nazrul Islam." },
  "dooriyaan-1979": { wikiTitle: "Dooriyaan", extract: "Dooriyaan (Hindi pronunciation: [duːriːjɑ̃]; transl. Distances) is a 1979 Hindi-language drama film co-written, produced and directed by Bhimsain under the banner of Climb Films, from a story by Shanker Shesh. It stars Uttam Kumar and Sharmila Tagore in the lead roles, while Shreeram Lagoo, Kireet Khurana and Sudha Chopra play supporting roles. The film follows a married and career-focused couple's personal ambitions leading to marital discord and their eventual separation.", director: "Bhimsain" },
  "srikanter-will-1979": { wikiTitle: "Srikanter Will", extract: "Srikanter Will is a 1979 Indian Bengali action drama film directed by Dinen Gupta. The film was released under the banner of Jaganmata Films and its music was composed by Salil Chowdhury. The film starred Uttam Kumar, Sumitra Mukherjee and Ranjit Mallick in lead roles.", director: "Dinen Gupta" },
  "pankhiraj-1980": { wikiTitle: "Pankhiraj", extract: "Pankhiraj (English:Lord of Birds) is a 1980 Indian Bengali action film written and directed by Pijush Basu. It had an ensemble cast consisting of Uttam Kumar, Soumitra Chatterjee, Nandita Bose, Utpal Dutt, Samit Bhanja and Santu Mukherjee in lead roles, while Tarun Kumar, Chinmoy Roy, Shambhu Bhattacharya, Durgadas Banerjee and Anamika Saha play another pivotal roles.", director: "Pijush Basu" },
  "rajnandini-1980": { wikiTitle: "Rajnandini", extract: "Rajnandini (transl. The Princess) is a Bengali romantic drama film directed by Sukhen Das. This film was released in 1980 under the banner of S.D Films.", director: "Sukhen Das" },
  "aro-ekjan-1980": { wikiTitle: "Aro Ekjan", extract: "Aro Ekjan is a Bengali action drama film directed by Srijan based on the same name novel of Ashutosh Mukhopadhyay. The film was released on 4 April 1980 under the banner of Baba Taraknath Chitramandir.", director: "Srijan" },
  "dui-prithibi-1980": { wikiTitle: "Dui Prithibi (1980 film)", extract: "Dui Prithibi (Bengali pronunciation: [dui pʰr̩iˈbʱi]; transl. Two Worlds) is a 1980 Bengali crime drama film co-written and directed by Pijush Basu. Produced by Uttam Kumar under the banner of Shilpi Sangshad, the film stars Kumar himself, alongside an ensemble cast of Ranjit Mallick, Victor Banerjee, Supriya Devi, Tanusree Shankar and Kalyani Mondal, with Prosenjit Chatterjee in a special appearance.\nAnanda Shankar scored the music of the movie.", director: "Pijush Basu" },
  "raja-saheb-1980": { wikiTitle: "Raja Saheb", extract: "Raja (; from IAST rājan-) is a noble or royal Sanskrit title historically used by some Indian rulers and monarchs and highest-ranking nobles. The title was historically used in the Indian subcontinent and Southeast Asia.\nThe title has a long history in South Asia and Southeast Asia, being attested from the Rigveda, where a rājan- is a ruler, see for example the daśarājñá yuddhá, the \"Battle of Ten Kings\"." },
  "plot-no-5-1981": { wikiTitle: "Plot No. 5", extract: "Plot No. 5 is a 1981 Indian Hindi-language psychological action thriller film directed by Yogesh Saxena and produced by Jerooant Yogesh. This film was released on 23 January 1981 under the banner of Visual Productions.", director: "Yogesh Saxena" },
  "ogo-bodhu-shundori-1981": { wikiTitle: "Ogo Bodhu Shundori", extract: "Ogo Bodhu Shundori (Bengali pronunciation: [ˈoɡo ˈbɔd̪ʱu ʃunˈd̪ɔri] transl. Hey Beautiful Bride) is a 1981 Bengali masala film directed by Salil Dutta. Produced and conceptualized by Kamal Bansal under the banner of R. D. B. & Co., the title of the film is taken from a Rabindra Sangeet of the same name. It stars Uttam Kumar, Ranjit Mallick, Moushumi Chatterjee and Sumitra Mukherjee in lead roles, with a supporting cast including Santosh Dutta, Bikash Roy, Haradhan Banerjee and Chinmoy Roy.", director: "Salil Dutta. Produced" },
  "khana-baraha-1981": { wikiTitle: "Khana Baraha", extract: "Khana Baraha is a Bengali historical drama film directed by Bijoy Bose and produced by Ashim Sarkar. This film was based on the story of Manmatha Roy about the life of Khana and Varāhamihira, the ancient mathematician astrologers of India. It was released on 29 May 1981.", director: "Bijoy Bose" },
  "surya-sakkhi-1981": { wikiTitle: "Surya Sakkhi", extract: "Surya Sakkhi (English: The Sun is The Witness) is a 1981 Indian Bengali romantic drama film directed by Agradoot. This film was released under the banner of Manjir Films.", director: "Agradoot" },
  "kalankini-kankabati-1981": { wikiTitle: "Kalankini Kankabati", extract: "Kalankini Kankabati (Bengali pronunciation: [kɔlɔŋkini kɔŋkaboti] transl. Kankabati is Stigmatized) is a 1981 Indian Bengali epic period action drama film directed by Pijush Basu and Uttam Kumar. Produced by Subrata Mukherjee and Sutanu Chatterjee under the banner of Beena Films, the film is based on a novel of the same name by Nihar Ranjan Gupta. It plots the tragedy of a royal family, where the love affairs of each king with courtesans consequent their cursed lives.", director: "Pijush Basu" },
  "desh-premee-1982": { wikiTitle: "Desh Premee", extract: "Desh Premee (transl. The Patriot) is a 1982 Hindi action film directed by Manmohan Desai, starring Amitabh Bachchan in a dual role alongside Hema Malini, Sharmila Tagore, Navin Nischol, Parveen Babi, Uttam Kumar, Shammi Kapoor, Premnath, Parikshit Sahni, Amjad Khan and Gita Siddharth. The film has musical score by Laxmikant-Pyarelal.\nIt was the fifth collaboration of Manmohan Desai and Amitabh Bachchan.", director: "Manmohan Desai" },
  "mera-karam-mera-dharam-1987": { wikiTitle: "Mera Karam Mera Dharam", extract: "Mera Karam Mera Dharam (transl. My deed, my religion) is a 1987 Bollywood film, starring Dharmendra and Moushumi Chatterjee. The movie was shot in Murshidabad kathgola Palace, West Bengal." },
  "oti-uttam-2024": { wikiTitle: "Oti Uttam", extract: "Oti Uttam is a 2024 Indian Bengali fantasy comedy film written, co-produced and directed by Srijit Mukherji under Camellia Productions and Matchcut Productions. Veteran Bengali actor Uttam Kumar appears on the screen through Visual effects from his existing clippings from his various films. His character was built by the scenes of his 56 existing old movies.", director: "Srijit Mukherji" },
};
